func isClassLikeMemberCompletion(symbol *ast.Symbol, location *ast.Node, file *ast.SourceFile) bool {
 if location == nil || ast.IsInJSFile(location) || symbol.Flags & (ast.SymbolFlagsClassMember & ast.SymbolFlagsEnumMemberExcludes) == 0 {return false}
 if ast.IsClassLike(location) {return true}
 p := location.Parent
 return p != nil && p.Parent != nil && ast.IsClassElement(p) && location == p.Name() && lsutil.GetLastToken(p,file)==location && ast.IsClassLike(p.Parent)
}

// EmbeddedClassMemberCompletion reuses the compiler's missing-member builder.
// All AST/checker values remain inside the active language-service operation.
func (l *LanguageService) EmbeddedClassMemberCompletion(ctx context.Context, ch *checker.Checker, file *ast.SourceFile, symbol *ast.Symbol, location *ast.Node, snippet bool) (string, []*lsproto.TextEdit, error) {
 if !isClassLikeMemberCompletion(symbol, location, file) { return "", nil, nil }
 enclosing := ast.FindAncestor(location, ast.IsClassLike)
 if enclosing == nil { return "", nil, nil }
 tracker := change.NewTracker(ctx, l.GetProgram().Options(), l.FormatOptions(), l.converters)
 adder, err := createImportAdder(ctx, &CodeFixContext{SourceFile:file, Program:l.GetProgram(), LS:l}, ch)
 if err != nil { return "", nil, err }
 fixer := newMissingMemberFixer(tracker, l.GetProgram(), ch, l.UserPreferences(), adder, locale.FromContext(ctx))
 var statements []*ast.Node
 if snippet { statements = append(statements, tracker.NodeFactory.NewExpressionStatement(tracker.NodeFactory.NewIdentifier("__goya_completion_tabstop__"))) }
 body := tracker.NodeFactory.NewBlock(tracker.NodeFactory.NewNodeList(statements), true)
 nodes := fixer.createMemberFromSymbol(symbol, enclosing, file, body, 0)
 var texts []string
 p := createSnippetPrinter(printer.PrinterOptions{RemoveComments:true, NewLine:core.GetNewLineKind(l.FormatOptions().NewLineCharacter)})
 for _, node := range nodes {
  text := p.printAndFormatNode(ctx, node, file)
  if snippet { text = strings.Replace(text, "__goya_completion_tabstop__;", "$0", 1) }
  texts = append(texts, text)
 }
 var edits []*lsproto.TextEdit
 if adder != nil && adder.HasFixes() { edits = adder.Edits() }
 return strings.Join(texts, l.FormatOptions().NewLineCharacter), edits, nil
}

