// EmbeddedCompletionCallParameters returns detached placeholders from the same
// typed signature used for completion details, including optional/rest handling.
func (l *LanguageService) EmbeddedCompletionCallParameters(ctx context.Context, item *lsproto.CompletionItem) ([]string, bool, bool, error) {
 data := item.Data
 if data == nil { return nil, false, false, nil }
 program, file := l.tryGetProgramAndFile(data.FileName)
 if file == nil { return nil, false, false, nil }
 ch, done := program.GetTypeCheckerForFile(ctx,file)
 defer done()
 token := astnav.GetTouchingToken(file,int(data.Position))
 if token != nil {
  if ast.FindAncestor(token,func(n *ast.Node)bool{return ast.IsBindingElement(n)||ast.IsImportDeclaration(n)})!=nil {return nil,false,false,nil}
  if symbol:=ch.GetSymbolAtLocation(token);symbol!=nil && symbol.Flags&(ast.SymbolFlagsVariable|ast.SymbolFlagsAlias)!=0 {return nil,false,false,nil}
 }
 details := l.getSymbolCompletionFromItemData(ctx,ch,file,int(data.Position),data)
 if details.symbol == nil {return nil,false,false,nil}
 t := ch.GetTypeOfSymbolAtLocation(details.symbol.symbol,details.symbol.location)
 signatures := ch.GetSignaturesOfType(t,checker.SignatureKindCall)
 if len(signatures)==0 {return nil,false,false,nil}
 // Completion details must use the symbol's type at the completion location,
 // including contextual instantiations, as the completion itself does.
 if item.Detail!=nil {
  originals:=getSignaturesAtLocation(ch,details.symbol.symbol,checker.SignatureKindCall,details.symbol.location)
  if len(originals)==len(signatures) {
   container:=getContainerNode(details.symbol.location)
   flags:=typeFormatFlags|checker.TypeFormatFlagsWriteCallStyleSignature|checker.TypeFormatFlagsWriteTypeArgumentsOfSignature|checker.TypeFormatFlagsMultilineObjectLiterals
   detail:=*item.Detail
   for i,original:=range originals {
    before:=ch.SignatureToStringEx(original,container,flags,nil)
    after:=before
    node:=ch.SignatureToSignatureDeclaration(signatures[i],ast.KindCallSignature,details.symbol.location,nodebuilder.FlagsNoTruncation)
    if node!=nil {
     factory:=ast.NewNodeFactory(ast.NodeFactoryHooks{})
     if node.ParameterList()!=nil {
      for index,parameterNode:=range node.ParameterList().Nodes {
       parameter:=parameterNode.AsParameterDeclaration()
       if parameter.QuestionToken==nil || parameter.Type==nil || parameter.Type.Kind!=ast.KindUnionType || index>=len(signatures[i].Parameters()) {continue}
       source:=ast.GetDeclarationOfKind(signatures[i].Parameters()[index],ast.KindParameter)
       if source==nil || source.Type()==nil {continue}
       annotation:=source.Type()
       for annotation.Kind==ast.KindParenthesizedType {annotation=annotation.AsParenthesizedTypeNode().Type}
       explicit:=annotation.Kind==ast.KindUndefinedKeyword
       if annotation.Kind==ast.KindUnionType {for _,part:=range annotation.AsUnionTypeNode().Types.Nodes {if part.Kind==ast.KindUndefinedKeyword {explicit=true}}}
       if explicit {continue}
       var parts []*ast.Node
       for _,part:=range parameter.Type.AsUnionTypeNode().Types.Nodes {if part.Kind!=ast.KindUndefinedKeyword {parts=append(parts,part)}}
       if len(parts)==1 {parameter.Type=parts[0]} else if len(parts)>1 {parameter.Type=factory.NewUnionTypeNode(factory.NewNodeList(parts))}
      }
     }
     p:=printer.NewPrinter(printer.PrinterOptions{RemoveComments:true},printer.PrintHandlers{},nil)
     after=strings.TrimSuffix(strings.TrimSpace(p.Emit(node,file)),";")
    }
    detail=strings.Replace(detail,before,after,1)
   }
   item.Detail=&detail
  }
 }
 signature := ch.SignatureToSignatureDeclaration(signatures[0],ast.KindCallSignature,details.symbol.location,nodebuilder.FlagsNoTruncation)
 if signature == nil {return nil,false,false,nil}
 var required []string
 optional:=false
 if parameters:=signature.ParameterList();parameters!=nil {
  for _,node:=range parameters.Nodes {
   p:=node.AsParameterDeclaration()
   if p.DotDotDotToken!=nil {optional=true;break}
   if p.QuestionToken!=nil {optional=true;continue}
   if p.Name().Kind==ast.KindIdentifier && p.Name().Text()!="this" {required=append(required,p.Name().Text())}
  }
 }
 return required,optional,true,nil
}

