func (l *LanguageService) EmbeddedAutoImportDetails(ctx context.Context, item *lsproto.CompletionItem) error {
 data:=item.Data
 if data==nil || data.AutoImport==nil {return nil}
 from:=l.GetProgram().GetSourceFile(data.FileName)
