  if location==nil {return fmt.Errorf("auto import declaration unavailable: %s",data.Name)}
  if name:=location.Name();name!=nil {location=name}
  service:=NewLanguageService(l.projectPath,program,l.host,targetFile.FileName())
  format:=getCompletionDocumentationFormat(ctx)
