   info=strings.TrimPrefix(info,"function ")
   info="(alias) "+info+"\nexport "+data.Name
  }
  detail:="Auto import from '"+data.AutoImport.ModuleSpecifier+"'"
  if info!="" {detail+="\n"+info}
  item.Detail=nil
  createCompletionDetails(item,detail,documentation,format)
