// referenceDocumentation keeps the editor Markdown contract separate from the
// compiler's plain JSDoc text. All nodes are consumed within the query lease.
func (l *LanguageService) referenceDocumentation(c *checker.Checker, declaration *ast.Node, excludeParameters bool) string {
 if declaration == nil { return "" }
 jsdoc := getJSDocOrTag(c, declaration)
 if jsdoc == nil || declaration.Flags&ast.NodeFlagsReparsed == 0 && containsTypedefTag(jsdoc) { return "" }
 render := func(comments []*ast.Node) string {
  var b strings.Builder
  l.writeComments(&b,c,comments,true)
  return b.String()
 }
 comment := render(jsdoc.Comments())
 if jsdoc.Kind != ast.KindJSDoc { return comment }
 tags := jsdoc.AsJSDoc().Tags
 if tags == nil { return comment }
 rendered := []string{}
 for _,tag := range tags.Nodes {
  name := tag.TagName().Text()
  if excludeParameters && name == "param" { continue }
  body := render(tag.Comments())
  if (name == "return" || name == "returns") && body == "" { continue }
  label := "*@"+name+"*"
  switch tag.Kind {
  case ast.KindJSDocParameterTag,ast.KindJSDocPropertyTag:
   if tag.Name()!=nil { label += " `"+getEntityNameString(tag.Name())+"`" }
   body = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(body),"-"))
  case ast.KindJSDocAugmentsTag:
   if tag.ClassName()!=nil {label += " `"+getEntityNameString(tag.ClassName())+"`"}
   body = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(body),"-"))
  case ast.KindJSDocTemplateTag:
   names:=[]string{}
   for _,tp:=range tag.TypeParameters(){names=append(names,getEntityNameString(tp.Name()))}
   if len(names)>0{label += " `"+strings.Join(names,", ")+"`"}
   body = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(body),"-"))
  case ast.KindJSDocSeeTag:
   if reference:=tag.AsJSDocSeeTag().NameExpression;reference!=nil {
    var b strings.Builder
    l.writeNameLink(&b,c,reference.Name(),"",false,l.UserPreferences().DisplayPartsForJSDoc.IsTrue())
    if body!=""{b.WriteString(" "+body)}
    body=b.String()
   }
  case ast.KindJSDocThrowsTag:
   if expr:=tag.AsJSDocThrowsTag().TypeExpression;expr!=nil{body=scanner.GetTextOfNode(expr)+core.IfElse(body!=""," ","")+body}
  }
  if name=="example" || name=="default" {
   caption:=""
   if name=="example" && strings.HasPrefix(body,"<caption>") {
    if end:=strings.Index(body,"</caption>");end>=0 {
     after:=body[end+len("</caption>"):]
     if strings.HasPrefix(after,"\n")||strings.HasPrefix(after,"\r\n"){
      caption=body[len("<caption>"):end]+"\n"
      body=strings.TrimLeft(after,"\r\n")
     }
    }
   }
   hasFence:=false
   for _,line:=range strings.Split(body,"\n") { line=strings.TrimSpace(line);if strings.HasPrefix(line,"```")||strings.HasPrefix(line,"~~~"){hasFence=true;break} }
   if !hasFence { body="```typescript\n"+body+"\n```" }
   body=caption+body
  }
  if name=="author" {
   if start:=strings.LastIndex(body,"<");start>=0&&strings.HasSuffix(body,">")&&strings.Contains(body[start:],"@"){body=body[:start]+body[start+1:len(body)-1]}
  }
  if body!="" { if strings.ContainsAny(body,"\r\n"){label += "  \n"+body}else{label += " — "+body} }
  rendered=append(rendered,label)
 }
 if len(rendered)>0{comment += "\n\n"+strings.Join(rendered,"  \n\n")}
 return comment
}

