// ProvideReferenceSourceDefinition excludes ambient and unresolved-alias
// fallbacks, matching the reference server's findSourceDefinition filtering.
// Mapped targets are inspected in their original source, so a .d.ts.map can
// still lead to a concrete TS declaration outside the current program.
func (l *LanguageService) ProvideReferenceSourceDefinition(ctx context.Context, documentURI lsproto.DocumentUri, position lsproto.Position) (lsproto.DefinitionResponse,error) {
 response,err:=l.ProvideSourceDefinition(ctx,documentURI,position)
 if err!=nil{return response,err}
 program,file:=l.getProgramAndFile(documentURI)
 resolver:=l.newSourceDefResolver(program,file.FileName())
 accept:=func(uri lsproto.DocumentUri,selection lsproto.Range)bool{
  if ctx.Err()!=nil{return false}
  name:=uri.FileName()
  if tspath.IsDeclarationFileName(name){return false}
  target:=resolver.getOrParseSourceFile(name)
  if target==nil{return false}
  node:=astnav.GetTouchingPropertyName(target,int(l.converters.LineAndCharacterToPosition(target,selection.Start)))
  if decl:=ast.GetDeclarationFromName(node);decl!=nil{node=decl}
  if node.Flags&ast.NodeFlagsAmbient!=0{return false}
  // A successfully resolved alias points at its declaration; remaining import
  // or re-export declarations represent failed alias resolution.
  switch node.Kind {
  case ast.KindImportSpecifier,ast.KindImportClause,ast.KindNamespaceImport,ast.KindImportEqualsDeclaration,ast.KindExportSpecifier,ast.KindExportDeclaration:
   return false
  }
  return true
 }
 if response.DefinitionLinks!=nil{
  links:=core.Filter(*response.DefinitionLinks,func(link *lsproto.LocationLink)bool{return accept(link.TargetUri,link.TargetSelectionRange)})
  response.DefinitionLinks=&links
 }
 if response.Locations!=nil{
  locations:=core.Filter(*response.Locations,func(loc lsproto.Location)bool{return accept(loc.Uri,loc.Range)})
  response.Locations=&locations
 }
 if response.Location!=nil&&!accept(response.Location.Uri,response.Location.Range){response.Location=nil;locations:=[]lsproto.Location{};response.Locations=&locations}
 return response,ctx.Err()
}

