  definition:=node.Kind==ast.KindDefaultKeyword||ast.GetDeclarationFromName(node)!=nil||ast.IsLiteralComputedPropertyDeclarationName(node)||(node.Kind==ast.KindConstructorKeyword&&ast.IsConstructorDeclaration(node.Parent))
