 for _,single:=range imports.singleReferences {if ast.IsIdentifier(single)&&ast.IsImportTypeNode(single.Parent) {nodes=append(nodes,single)}}
 searchName:=name
 if isDefault {searchName="default"}
 for _,file:=range imports.indirectUsers {
  if err:=ctx.Err();err!=nil {return nil,err}
  for _,node:=range getPossibleSymbolReferenceNodes(file,searchName,nil) {
   symbol:=ch.GetSymbolAtLocation(node)
   assignment:=false
   if symbol!=nil {for _,declaration:=range symbol.Declarations {if ast.IsExportAssignment(declaration) {assignment=true;break}}}
   if ast.IsIdentifier(node)&&!ast.IsImportSpecifier(node.Parent)&&!ast.IsExportSpecifier(node.Parent)&&(symbol==exportSymbol||assignment) {nodes=append(nodes,node)}
  }
 }
