    }else if ast.IsComputedPropertyName(node.Name()){
     expression:=node.Name().Expression();name=""
     if ast.IsStringOrNumericLiteralLike(expression){name=expression.Text()}
    }else if ast.IsStringLiteralLike(node.Name()){name=node.Name().Text()}
