   var children []*lsproto.DocumentSymbol
   for _,symbol:=range g.symbols{if symbol.Children!=nil{children=append(children,(*symbol.Children)...)} }
   children=finish(children)
   first:=g.symbols[0]
   for _,symbol:=range g.symbols{
    included:=[]*lsproto.DocumentSymbol{}
    for _,child:=range children{if lsproto.ComparePositions(child.Range.Start,symbol.Range.End)<=0&&lsproto.ComparePositions(child.Range.End,symbol.Range.Start)>=0{included=append(included,child)}}
