func ProvideReferenceWorkspaceSymbols(ctx context.Context,programs []*compiler.Program,converters *lsconv.Converters,preferences lsutil.UserPreferences,query string)([]*lsproto.SymbolInformation,error){
 matcher:=editorpattern.New(query)
 if matcher==nil{return []*lsproto.SymbolInformation{},nil}
 type item struct{name string;node *ast.Node;match int}
 var items []item
 seen:=map[tspath.Path]bool{}
 for _,program:=range programs{
  for _,file:=range program.SourceFiles(){
   if seen[file.Path()]||shouldExcludeFile(file,program,preferences.ExcludeLibrarySymbolsInNavTo.IsTrue()){continue};seen[file.Path()]=true
   if err:=ctx.Err();err!=nil{return nil,err}
   declarations:=make(map[string][]*ast.Node)
   for name,nodes:=range file.GetDeclarationMap(){declarations[name]=nodes}
   // Native named-declaration indexing omits default import identifiers.
   // Keep the name span (TS6's import-clause item), without mutating its cache.
   for _,statement:=range file.Statements.Nodes{
    if !ast.IsImportDeclaration(statement){continue}
    clause:=statement.AsImportDeclaration().ImportClause
    if clause!=nil&&clause.Name()!=nil{
     n:=clause.Name();name:=n.Text()
     if !slices.Contains(declarations[name],n){declarations[name]=append(slices.Clone(declarations[name]),n)}
    }
   }
   // Map iteration must not decide ordering of equal-named declarations.
   var names []string;for name:=range declarations{names=append(names,name)};slices.Sort(names)
   for _,name:=range names{
    for _,node:=range declarations[name]{
     importNode:=node
     if ast.IsIdentifier(node)&&ast.IsImportClause(node.Parent){importNode=node.Parent}
     if ast.IsImportClause(importNode)||ast.IsImportSpecifier(importNode)||ast.IsImportEqualsDeclaration(importNode){
      ch,done:=program.GetTypeChecker(ctx)
      symbol:=ch.GetSymbolAtLocation(importNode.Name())
      keep:=false
      if symbol!=nil{aliased:=ch.GetAliasedSymbol(symbol);if aliased!=nil&&(ast.IsImportClause(importNode)||aliased.Name!=symbol.Name){keep=true;allExcluded:=len(aliased.Declarations)>0;for _,decl:=range aliased.Declarations{sf:=ast.GetSourceFileOfNode(decl);if !shouldExcludeFile(sf,program,preferences.ExcludeLibrarySymbolsInNavTo.IsTrue()){allExcluded=false;break}};keep=keep&&!allExcluded}}
      done();if !keep{continue}
     }
     var containers []string
     for parent:=getContainerNode(node);parent!=nil;parent=getContainerNode(parent){
      n:=ast.GetNameOfDeclaration(parent)
      if n==nil{containers=nil;break}
      if ast.IsIdentifier(n)||ast.IsStringOrNumericLiteralLike(n){containers=append(containers,n.Text())}else{containers=nil;break}
     }
     slices.Reverse(containers)
     match:=matcher.Match(name,containers);if match!=nil{items=append(items,item{name,node,match.Kind})}
    }
   }
  }
 }
 order:=collate.New(language.English,collate.Numeric)
 slices.SortStableFunc(items,func(a,b item)int{if a.match!=b.match{return a.match-b.match};return order.CompareString(a.name,b.name)})
 result:=make([]*lsproto.SymbolInformation,0,len(items))
 for _,i:=range items{
  file:=ast.GetSourceFileOfNode(i.node)
  result=append(result,&lsproto.SymbolInformation{Name:i.name,Kind:referenceSymbolKind(i.node),Location:converters.ToLSPLocation(file,core.NewTextRange(astnav.GetStartOfNode(i.node,file,false),i.node.End()))})
 }
 return result,ctx.Err()
}

