func referenceCodeFixName(provider *CodeFixProvider)string{
 if provider.Name!=""{return provider.Name}
 switch provider{
 case ImportFixProvider:return "import"
 case IsolatedDeclarationsFixProvider:return "fixMissingTypeAnnotationOnExports"
 case FixClassIncorrectlyImplementsInterfaceProvider:return "fixClassIncorrectlyImplementsInterface"
 }
 return ""
}
func(l *LanguageService)ProvideReferenceCodeFixes(ctx context.Context,uri lsproto.DocumentUri,diagnostic *lsproto.Diagnostic)([]ReferenceCodeFixAction,error){
 copy:=*l;copy.activeConfig.IncludeCompletionsForModuleExports=core.TSTrue;l=&copy
 program,file:=l.getProgramAndFile(uri)
 span:=l.converters.FromLSPRange(file,diagnostic.Range)
 code:=*diagnostic.Code.Integer
 result:=[]ReferenceCodeFixAction{}
 for _,provider:=range codeFixProviders{
  if err:=ctx.Err();err!=nil{return nil,err}
  if !containsErrorCode(provider.ErrorCodes,code){continue}
  request:=&CodeFixContext{SourceFile:file,Span:span,ErrorCode:code,Program:program,LS:l,Diagnostic:diagnostic}
  actions,err:=provider.GetCodeActions(ctx,request);if err!=nil{return nil,err}
  availabilityCodes:=provider.ErrorCodes;if provider.ReferenceFixAllErrorCodes!=nil{availabilityCodes=provider.ReferenceFixAllErrorCodes}
  available:=hasMultipleFixableDiagnostics(ctx,program,file,availabilityCodes)
  for _,action:=range actions{
   owned:=*action;if !available{owned.FixID="";owned.FixAllDescription=""};action=&owned
   fixName:=action.ReferenceFixName;if fixName==""{fixName=referenceCodeFixName(provider)}
   result=append(result,ReferenceCodeFixAction{FixName:fixName,Description:action.Description,Changes:referenceActionChanges(file,action),FixID:action.FixID,FixAllDescription:action.FixAllDescription})
  }
 }
 return result,ctx.Err()
}
func(l *LanguageService)ProvideReferenceCombinedCodeFix(ctx context.Context,uri lsproto.DocumentUri,fixID string)([]ReferenceFileCodeChanges,error){
 copy:=*l;copy.activeConfig.IncludeCompletionsForModuleExports=core.TSTrue;l=&copy
 program,file:=l.getProgramAndFile(uri)
 for _,provider:=range codeFixProviders{
  if err:=ctx.Err();err!=nil{return nil,err}
  if !slices.Contains(provider.FixIds,fixID)||provider.GetAllCodeActions==nil{continue}
  action,err:=provider.GetAllCodeActions(ctx,&CodeFixContext{SourceFile:file,Program:program,LS:l,FixID:fixID});if err!=nil{return nil,err}
  if action==nil{return []ReferenceFileCodeChanges{},nil}
  if action.ReferenceChanges!=nil{return action.ReferenceChanges,ctx.Err()}
  if len(action.Changes)==0{return []ReferenceFileCodeChanges{},nil}
  return []ReferenceFileCodeChanges{{FileName:file.FileName(),TextChanges:action.Changes}},ctx.Err()
 }
 return []ReferenceFileCodeChanges{},nil
}
func ReferenceSupportedCodeFixes()[]int32{
 codes:=map[int32]bool{};for _,provider:=range codeFixProviders{for _,code:=range provider.ErrorCodes{codes[code]=true}}
 result:=make([]int32,0,len(codes));for code:=range codes{result=append(result,code)};slices.Sort(result);return result
}

func referenceActionChanges(file *ast.SourceFile,action *CodeAction)[]ReferenceFileCodeChanges{
 if action.ReferenceChanges!=nil{return action.ReferenceChanges}
 return []ReferenceFileCodeChanges{{FileName:file.FileName(),TextChanges:action.Changes}}
}
