  index:=slices.Index(owner.Parameters(),parameter);referent:=owner;if ast.IsMethodDeclaration(owner){referent=owner.Name()}
  entries:=request.LS.GetReferencedSymbolsForNode(ctx,owner.Pos(),referent,request.Program.GetSourceFiles())
  for _,entry:=range entries{for _,reference:=range entry.References(){
   node:=reference.Node();if node==nil||node.Parent==nil{continue}
   if node.Kind==ast.KindSuperKeyword&&ast.IsCallExpression(node.Parent)&&len(node.Parent.Arguments())>index{return false}
   if ast.IsPropertyAccessExpression(node.Parent)&&node.Parent.Expression().Kind==ast.KindSuperKeyword&&node.Parent.Parent!=nil&&ast.IsCallExpression(node.Parent.Parent)&&len(node.Parent.Parent.Arguments())>index{return false}
   if (ast.IsMethodDeclaration(node.Parent)||ast.IsMethodSignatureDeclaration(node.Parent))&&node.Parent!=owner&&len(node.Parent.Parameters())>index{return false}
  }}
