  name:=owner.Name();if name!=nil{for _,reference:=range referenceUnusedReferences(ch,request.SourceFile,name){
   if reference.Parent!=nil&&ast.IsCallExpression(reference.Parent)&&slices.Contains(reference.Parent.Arguments(),reference){return referenceUnusedLastParameter(ch,parameter,all)}
  }}
