 var declaration *ast.Node
 for _,candidate:=range symbol.Declarations{if ast.IsClassLike(candidate){declaration=candidate;break}}
 if declaration==nil && ast.IsPrivateIdentifier(token){return nil}
 if declaration==nil{for _,candidate:=range symbol.Declarations{if ast.IsInterfaceDeclaration(candidate)||ast.IsTypeLiteralNode(candidate){declaration=candidate;break}}}
