 if declaration==nil && typ.Flags()&checker.TypeFlagsEnumLike==0{for _,candidate:=range symbol.Declarations{if ast.IsEnumDeclaration(candidate){declaration=candidate;enum=true;break}}}
 if declaration==nil{return nil}
