 type otherKey struct{owner *ast.Node;name string;token *ast.Node};seenOther:=map[otherKey]bool{}
 for _,diagnostic:=range getAllDiagnostics(ctx,request.Program,request.SourceFile){
  if err:=ctx.Err();err!=nil{return nil,err}
  if !slices.Contains(referenceMissingMemberCodes,diagnostic.Code()){continue}
  individual:=*request;individual.Span=diagnostic.Loc();individual.ErrorCode=diagnostic.Code()
  if other:=referenceOtherMissingMemberInfo(&individual,ch);other!=nil{
   key:=otherKey{owner:other.owner,name:other.identifier}
   if other.kind=="object"{if key.name==""{key.token=other.token}}else{key.name=other.token.Text()}
   if seenOther[key]{continue};seenOther[key]=true
   applicable:=(request.FixID=="fixMissingProperties"&&other.kind=="object")||(request.FixID=="fixMissingAttributes"&&other.kind=="jsx")||(request.FixID=="fixMissingFunctionDeclaration"&&(other.kind=="function"||other.kind=="signature"))
   if applicable{if err:=referenceApplyOtherMissingMember(ctx,request,ch,tracker,other);err!=nil{return nil,err}}
   continue
  }
  info:=referenceMissingTypeMemberInfo(&individual,ch);if info==nil{continue}
  if info.enum {
   key:=info.declaration
   if !slices.ContainsFunc(groups[key],func(other *referenceMissingTypeMember)bool{return other.token.Text()==info.token.Text()}){
    groups[key]=append(groups[key],info);referenceInsertMissingEnumMember(ch,tracker,info)
   }
   continue
  }
  infos,exists:=groups[info.declaration]
  if !exists{declarations=append(declarations,info.declaration)}
  if !slices.ContainsFunc(infos,func(other *referenceMissingTypeMember)bool{return other.token.Text()==info.token.Text()}){groups[info.declaration]=append(infos,info)}
