   seen[declaration]=true
   element:=ast.GetClassExtendsHeritageElement(declaration);if element==nil{break}
   symbol:=ch.GetSymbolAtLocation(element.Expression());if symbol==nil{break}
   if symbol.Flags&ast.SymbolFlagsAlias!=0{symbol=ch.GetAliasedSymbol(symbol)}
