  if ast.IsReturnStatement(info.owner){tracker.InsertNodeBefore(info.file,info.owner,node,true,change.LeadingTriviaOptionNone)}else{tracker.InsertReferenceNodeAtEndOfScope(info.file,info.owner,node)}
 case "object":
  properties:=slices.Clone(info.owner.AsObjectLiteralExpression().Properties.Nodes)
  for _,prop:=range info.properties{properties=append(properties,tracker.NewPropertyAssignment(nil,builder.propertyName(prop),nil,nil,builder.value(ch.GetTypeOfSymbol(prop),info.owner)))}
  tracker.ReplaceReferenceObjectLiteral(info.file,info.owner,tracker.NewObjectLiteralExpression(tracker.NewNodeList(properties),true),info.zeroIndent)
 case "jsx":
  attrs:=info.owner.Attributes();old:=attrs.AsJsxAttributes().Properties.Nodes;added:=[]*ast.Node{}
  for _,prop:=range info.properties{
   name:=tracker.NewIdentifier(ast.SymbolName(prop));node:=tracker.NewJsxAttribute(name,tracker.NewJsxExpression(nil,builder.value(ch.GetTypeOfSymbol(prop),info.owner)));name.Parent=node;added=append(added,node)
  }
  if slices.ContainsFunc(old,ast.IsJsxSpreadAttribute){added=append(added,old...)}else{added=append(slices.Clone(old),added...)}
  options:=&change.NodeOptions{};if attrs.Pos()==attrs.End(){options.Prefix=" "}
  tracker.ReplaceNode(info.file,attrs,tracker.NewJsxAttributes(tracker.NewNodeList(added)),options)
 }
 if builder.err!=nil{return builder.err}
 if adder!=nil{for _,edit:=range adder.Edits(){tracker.ReplaceRangeWithText(request.SourceFile,edit.Range,edit.NewText)}}
 return ctx.Err()
}
