 switch referenceInferenceSuggestToError(code) {
 case 7006:if fn:=ast.GetContainingFunction(token);fn==nil||!ast.IsSetAccessorDeclaration(fn) {message=diagnostics.Infer_parameter_types_from_usage}
 case 7019:message=diagnostics.Infer_parameter_types_from_usage
