   if typ.Flags()&checker.TypeFlagsPrimitive==0&&typ.ObjectFlags()&checker.ObjectFlagsClass==0&&!ch.IsArrayType(typ)&&!checker.IsTupleType(typ) {
    // Direct import lookup uses getPropertyOfType, including inherited members.
    // Enumerate candidate names from the program's own global prototypes, then
    // resolve them on the export type instead of assuming any builtin exists.
    for _,global:=range []string{"Object","Function","CallableFunction","NewableFunction"} {
     if symbol:=ch.ResolveName(global,nil,ast.SymbolFlagsType,false);symbol!=nil {
      for _,candidate:=range ch.GetPropertiesOfType(ch.GetDeclaredTypeOfSymbol(symbol)) {if member:=ch.GetPropertyOfType(typ,candidate.Name);member!=nil {members=append(members,member)}}
     }
    }
   }
   seen:=map[string]bool{}
   for _,namedExport:=range members {
    if seen[namedExport.Name]||namedExport.Name==ast.InternalSymbolNameExportStar||namedExport.Name==ast.InternalSymbolNameExportEquals {continue};seen[namedExport.Name]=true
    var exported *Export
    if namedExport.Flags&ast.SymbolFlagsPrototype!=0 {
     exported=&Export{ExportID:ExportID{ModuleID:moduleID,ExportName:namedExport.Name},ModuleFileName:moduleFileName,Syntax:syntax,Flags:namedExport.Flags,Path:file.Path(),PackageName:e.packageName,Target:ExportID{ModuleID:moduleID,ExportName:namedExport.Name},ScriptElementKind:lsutil.ScriptElementKindMemberVariableElement}
    } else {exported,_=e.createExport(namedExport,moduleID,moduleFileName,syntax,file,checkerLease)}
    if exported!=nil {exported.through=name;exported.referenceImportOnly=!ordinary[namedExport.Name];exported.referenceCommonJSNamespace=referenceDefaultImportNamespace(target,ch);*exports=append(*exports,exported)}
   }
  }

// The reference chooses the first declaration/name along the immediate alias
// chain before falling back to its exporting module's file-name spelling.
func referenceDefaultImportNamespace(symbol *ast.Symbol,ch *checker.Checker) string {
 seen:=map[*ast.Symbol]bool{};chain:=[]*ast.Symbol{}
 for current:=symbol;current!=nil&&!seen[current]; {
  if name:=getDefaultLikeExportNameFromDeclaration(current);name!="" {return name}
  if current.Name!=ast.InternalSymbolNameDefault&&current.Name!=ast.InternalSymbolNameExportEquals {return current.Name}
  seen[current]=true;chain=append(chain,current)
  if current.Flags&ast.SymbolFlagsAlias!=0 {current=ch.GetImmediateAliasedSymbol(current)} else {current=nil}
 }
 for _,current:=range chain {if current.Parent!=nil&&checker.IsExternalModuleSymbol(current.Parent) {return lsutil.ModuleSymbolToValidIdentifier(current.Parent,false)}}
 return ""
}
