func ReferenceViewForFile(view *View,file *ast.SourceFile,future bool)*View{
 result:=NewView(view.registry,file,view.projectKey,view.program,view.preferences,view.packageJsonAutoImports)
 if future{
  p:=view.program;name:=file.FileName();directory:=p.GetNearestAncestorDirectoryWithPackageJson(tspath.GetDirectoryPath(name));kind:=""
  if directory!=""{if info:=p.GetPackageJsonInfo(tspath.CombinePaths(directory,"package.json"));info!=nil&&info.Contents!=nil{if value,ok:=info.Contents.Type.GetValue();ok{resolution:=p.Options().GetModuleResolutionKind();if (!tspath.FileExtensionIsOneOf(name,[]string{tspath.ExtensionMts,tspath.ExtensionCts,tspath.ExtensionMjs,tspath.ExtensionCjs})&&resolution>=core.ModuleResolutionKindNode16&&resolution<=core.ModuleResolutionKindNodeNext)||strings.Contains(name,"/node_modules/"){kind=value}}}}
  metadata:=ast.SourceFileMetaData{PackageJsonType:kind,PackageJsonDirectory:directory,ImpliedNodeFormat:ast.GetImpliedNodeFormatForFile(name,kind)}
  // The pinned createFutureSourceFile copies only an object result from
  // getImpliedNodeFormatForFileWorker. Explicit .mts/.cts formats are numeric
  // results and are intentionally absent on that future-file object.
  if tspath.FileExtensionIsOneOf(name,[]string{tspath.ExtensionMts,tspath.ExtensionCts,tspath.ExtensionMjs,tspath.ExtensionCjs}){metadata=ast.SourceFileMetaData{}}
  host:=&referenceFutureSpecifierHost{Program:p,fileName:name,metadata:metadata}
  result.referenceFutureHost=host
  result.conditions=collections.NewSetFromItems(module.GetConditions(p.Options(),host.GetDefaultResolutionModeForFile(file))...)
 }
 return result
}
