func ReferenceModuleImportFix(ctx context.Context,view *View,c *checker.Checker,alias,reference *ast.Node,symbol *ast.Symbol)*Fix{
 target:=c.SkipAlias(symbol)
 if target==nil||target.Flags&ast.SymbolFlagsModule==0{panic(&change.InvalidEdits{Reason:"module import does not refer to a module"})}
 specifiers,kind:=modulespecifiers.GetModuleSpecifiersWithInfo(target,c,view.program.Options(),view.importingFile,view.referenceSpecifierHost(),view.preferences,modulespecifiers.ModuleSpecifierOptions{},true)
 if len(specifiers)==0{return nil}
 if id,_,ok:=tryGetModuleIDAndFileNameOfModuleSymbol(target);ok{
  for _,existing:=range view.getExistingImports(ctx).Get(id){if existing.moduleSpecifier!=""{specifiers[0]=existing.moduleSpecifier;break}}
 }
 importKind:=lsproto.ImportKindNamespace
 if ast.IsImportClause(reference)&&reference.Name()!=nil{importKind=lsproto.ImportKindDefault}
 addAs:=lsproto.AddAsTypeOnlyAllowed
 if ast.IsTypeOnlyImportDeclaration(reference){addAs=lsproto.AddAsTypeOnlyRequired}
 return &Fix{AutoImportFix:&lsproto.AutoImportFix{Kind:lsproto.AutoImportFixKindAddNew,Name:alias.Text(),ModuleSpecifier:specifiers[0],ImportKind:importKind,AddAsTypeOnly:addAs},ModuleSpecifierKind:kind}
}
func ReferenceFutureImportFix(ctx context.Context,view *View,name,file string,isDefault bool,flags ast.SymbolFlags,typeOnly bool)*Fix{
 if source:=view.program.GetSourceFile(file);source!=nil&&source.Symbol!=nil{
  exportName:=name;if isDefault{exportName=ast.InternalSymbolNameDefault}
  syntax:=ExportSyntaxModifier;if isDefault{syntax=ExportSyntaxDefaultDeclaration}
  entry:=&Export{ExportID:ExportID{ModuleID:ModuleID(source.Path()),ExportName:exportName},ModuleFileName:file,Syntax:syntax,Flags:flags,localName:name}
  entry.Target=entry.ExportID
  if fixes:=view.GetFixes(ctx,entry,false,typeOnly,nil);len(fixes)>0{return fixes[0]}
 }
 addAs:=getAddAsTypeOnly(typeOnly,&Export{Flags:flags},view.program.Options())
 kind:=lsproto.ImportKindNamed
 if isDefault{kind=lsproto.ImportKindDefault}
 // A future file is an ES module. Verbatim CommonJS imports retain the
 // reference's import-equals/destructuring policy through getImportKind.
 exporting:=&Export{Syntax:ExportSyntaxModifier,ExportID:ExportID{ExportName:name},Flags:flags}
 if isDefault{exporting.Syntax=ExportSyntaxDefaultDeclaration}
 kind=view.referenceImportKind(exporting)
 specifier:=modulespecifiers.ReferenceLocalModuleSpecifier(view.importingFile,file,view.program.Options(),view.referenceSpecifierHost(),view.preferences)
 return &Fix{AutoImportFix:&lsproto.AutoImportFix{Kind:lsproto.AutoImportFixKindAddNew,Name:name,ModuleSpecifier:specifier,ImportKind:kind,AddAsTypeOnly:addAs},ModuleSpecifierKind:modulespecifiers.ResultKindRelative}
}
