func ReferenceWriteExistingImport(t *change.Tracker,file *ast.SourceFile,clause *ast.Node,defaultImport *ReferenceImportBinding,named []ReferenceImportBinding,remove map[*ast.Node]bool,preferences lsutil.UserPreferences){
 if ast.IsObjectBindingPattern(clause){
  if core.Some(clause.Elements(),func(n *ast.Node)bool{return remove[n]}){
   nodes:=[]*ast.Node{};for _,node:=range clause.Elements(){if !remove[node]{nodes=append(nodes,node)}}
   if defaultImport!=nil{nodes=append(nodes,t.NewBindingElement(nil,t.NewIdentifier("default"),t.NewIdentifier(defaultImport.Name),nil))}
   for _,item:=range named{var property *ast.Node;if item.PropertyName!=""{property=t.NewIdentifier(item.PropertyName)};nodes=append(nodes,t.NewBindingElement(nil,property,t.NewIdentifier(item.Name),nil))}
   t.ReplaceNode(file,clause,t.NewBindingPattern(ast.KindObjectBindingPattern,t.NewNodeList(nodes)),nil)
  }else{
   if defaultImport!=nil{addElementToBindingPattern(t,file,clause.AsBindingPattern(),defaultImport.Name,"default")}
   for _,item:=range named{addElementToBindingPattern(t,file,clause.AsBindingPattern(),item.Name,item.PropertyName)}
  };return
 }
 if len(remove)==0||len(named)==0{addToExistingImport(t,file,clause,referenceBinding(defaultImport),referenceBindings(named),preferences);return}
 c:=clause.AsImportClause()
 if defaultImport!=nil{t.InsertNodeAt(file,core.TextPos(scanner.GetTokenPosOfNode(clause,file,false)),t.NewIdentifier(defaultImport.Name),change.NodeOptions{Suffix:", "})}
 promote:=c.IsTypeOnly()&&core.Some(referenceBindings(named),func(b *newImportBinding)bool{return b.addAsTypeOnly==lsproto.AddAsTypeOnlyNotAllowed})
 if defaultImport!=nil&&defaultImport.AddAsTypeOnly==lsproto.AddAsTypeOnlyNotAllowed&&c.IsTypeOnly(){promote=true}
 nodes:=[]*ast.Node{}
 for _,node:=range c.NamedBindings.Elements(){if !remove[node]{nodes=append(nodes,node)}}
 for _,item:=range named{var property *ast.Node;if item.PropertyName!=""{property=t.NewIdentifier(item.PropertyName)};nodes=append(nodes,t.NewImportSpecifier((!c.IsTypeOnly()||promote)&&shouldUseTypeOnly(item.AddAsTypeOnly,preferences),property,t.NewIdentifier(item.Name)))}
 compare,_:=lsutil.GetNamedImportSpecifierComparerWithDetection(c.Parent,file,preferences);slices.SortFunc(nodes,compare)
 t.ReplaceNode(file,c.NamedBindings,t.UpdateNamedImports(c.NamedBindings.AsNamedImports(),t.NewNodeList(nodes)),nil)
 if promote{
  keyword:=getTypeKeywordOfTypeOnlyImport(c,file);t.DeleteRange(file,core.NewTextRange(clause.Pos(),keyword.End()))
  for _,node:=range c.NamedBindings.Elements(){if !node.AsImportSpecifier().IsTypeOnly{t.InsertModifierBefore(file,ast.KindTypeKeyword,node)}}
 }
}

